def to_binary(n: int) -> str:
    """Return the binary representation of a non‑negative integer `n` as a string."""
    if n < 0:
        raise ValueError("n must be non‑negative")
    if n == 0:
        return "0"

    bits = []
    while n:
        bits.append('1' if n & 1 else '0')
        n >>= 1
    return ''.join(reversed(bits))


