def is_valid_email(s: str) -> bool:
    # Must contain exactly one '@'
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    # Local part and domain must be non‑empty
    if not local or not domain:
        return False
    # Domain must contain at least one dot, not at start/end
    if '.' not in domain or domain.startswith('.') or domain.endswith('.'):
        return False
    # No empty labels in domain (e.g., consecutive dots)
    if any(part == '' for part in domain.split('.')):
        return False
    return True

