def decode_rle(s):
    result = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j == i:
            # No leading digit; treat as single character (defensive)
            result.append(s[i])
            i += 1
            continue
        count = int(s[i:j])
        if j < n:
            result.append(s[j] * count)
            i = j + 1
        else:
            break
    return ''.join(result)
